INSERT INTO repo_subtopics (subtopic_id, name, subtopic_no, description, subtopic_sd_id, review_status, status, version) VALUES ('SUB_COURSE_028_M2_S2', 'virtual machines', '2', 'virtual machines: Software-defined computing environments that provide isolated execution of guest operating systems and applications on shared physical hardware. In Virtualization Technologies, the focus is on the analysis, design, implementation, interpretation, or evaluation of virtual machines within Cloud Computing and Virtualization, particularly where the Virtualization Technologies module establishes its technical context.', 'SSD_COURSE_028_M2_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_028_M2_S3', 'containers', '3', 'containers: OS-level application isolation units that package application code and dependencies while sharing a host operating-system kernel. In Virtualization Technologies, the focus is on concept-level scope: the defining mechanism, properties, constraints, and application criteria; curricular context is recorded in Concept_Category and Typical_Modules.', 'SSD_COURSE_028_M2_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_028_M2_S4', 'hardware virtualization', '4', 'hardware virtualization: Using a hypervisor or similar mechanism to create virtual machines from shared physical hardware. In Virtualization Technologies, the focus is on the analysis, design, implementation, interpretation, or evaluation of hardware virtualization within Cloud Computing and Virtualization, particularly where the Virtualization Technologies module establishes its technical context.', 'SSD_COURSE_028_M2_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_028_M2_S5', 'resource isolation', '5', 'resource isolation: Separating workloads so that one tenant or virtual machine cannot improperly affect another''s resources or data. In Virtualization Technologies, the focus is on the analysis, design, implementation, interpretation, or evaluation of resource isolation within Cloud Computing and Virtualization, particularly where the Virtualization Technologies module establishes its technical context.', 'SSD_COURSE_028_M2_S5', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_028_M3_S1', 'provisioning', '1', 'provisioning: Allocating and configuring cloud resources required to run a workload or service. In Cloud Resource Management, the focus is on the analysis, design, implementation, interpretation, or evaluation of provisioning within Cloud Computing and Virtualization, particularly where the Cloud Resource Management module establishes its technical context.', 'SSD_COURSE_028_M3_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_028_M3_S2', 'autoscaling', '2', 'autoscaling: Automatically increasing or decreasing resources in response to workload or policy conditions. In Cloud Resource Management, the focus is on the analysis, design, implementation, interpretation, or evaluation of autoscaling within Cloud Computing and Virtualization, particularly where the Cloud Resource Management module establishes its technical context.', 'SSD_COURSE_028_M3_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_028_M3_S3', 'scheduling', '3', 'scheduling: Selecting when and where cloud workloads should run subject to resource and policy constraints. In Cloud Resource Management, the focus is on the analysis, design, implementation, interpretation, or evaluation of scheduling within Cloud Computing and Virtualization, particularly where the Cloud Resource Management module establishes its technical context.', 'SSD_COURSE_028_M3_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_028_M3_S4', 'resource allocation', '4', 'resource allocation: Assigning compute, memory, storage, and network capacity to workloads according to defined objectives and constraints. In Cloud Resource Management, the focus is on the analysis, design, implementation, interpretation, or evaluation of resource allocation within Cloud Computing and Virtualization, particularly where the Cloud Resource Management module establishes its technical context.', 'SSD_COURSE_028_M3_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_028_M3_S5', 'capacity planning', '5', 'capacity planning: Estimating future resource demand and determining the compute, storage, network, or service capacity needed to meet performance and availability requirements. In Cloud Resource Management, the focus is on the analysis, design, implementation, interpretation, or evaluation of capacity planning within Cloud Computing and Virtualization, particularly where the Cloud Resource Management module establishes its technical context.', 'SSD_COURSE_028_M3_S5', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_028_M4_S1', 'object storage', '1', 'object storage refers to a storage architecture in which data are managed as objects containing payload data, metadata, and a unique identifier within a logical namespace. In Cloud Storage and Data Services, the focus is on concept-level scope: the defining mechanism, properties, constraints, and application criteria; curricular context is recorded in Concept_Category and Typical_Modules.', 'SSD_COURSE_028_M4_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_028_M4_S2', 'block storage', '2', 'block storage: Storage presented as addressable blocks that operating systems or applications can format and manage. In Cloud Storage and Data Services, the focus is on the analysis, design, implementation, interpretation, or evaluation of block storage within Cloud Computing and Virtualization, particularly where the Cloud Storage and Data Services module establishes its technical context.', 'SSD_COURSE_028_M4_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_028_M4_S3', 'file storage', '3', 'file storage: Shared storage that organises data as files and directories accessed through a file-system interface. In Cloud Storage and Data Services, the focus is on the analysis, design, implementation, interpretation, or evaluation of file storage within Cloud Computing and Virtualization, particularly where the Cloud Storage and Data Services module establishes its technical context.', 'SSD_COURSE_028_M4_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_028_M4_S4', 'distributed databases', '4', 'distributed databases: Databases whose data and processing are distributed across multiple networked nodes. In Cloud Storage and Data Services, the focus is on the analysis, design, implementation, interpretation, or evaluation of distributed databases within Cloud Computing and Virtualization, particularly where the Cloud Storage and Data Services module establishes its technical context.', 'SSD_COURSE_028_M4_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_028_M4_S5', 'data durability', '5', 'data durability refers to the likelihood that stored data remains intact and recoverable despite failures or loss events. In Cloud Storage and Data Services, the focus is on the analysis, design, implementation, interpretation, or evaluation of data durability within Cloud Computing and Virtualization, particularly where the Cloud Storage and Data Services module establishes its technical context.', 'SSD_COURSE_028_M4_S5', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_028_M5_S1', 'virtual networks', '1', 'virtual networks: Software-defined network structures that provide logical connectivity and isolation over shared infrastructure. In Cloud Networking, the focus is on the analysis, design, implementation, interpretation, or evaluation of virtual networks within Cloud Computing and Virtualization, particularly where the Cloud Networking module establishes its technical context.', 'SSD_COURSE_028_M5_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_028_M5_S2', 'subnets', '2', 'subnets: Logical subdivisions of an IP network used to organise addressing and routing. In Cloud Networking, the focus is on the analysis, design, implementation, interpretation, or evaluation of subnets within Cloud Computing and Virtualization, particularly where the Cloud Networking module establishes its technical context.', 'SSD_COURSE_028_M5_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_028_M5_S3', 'routing', '3', 'routing: Selection of paths through a network from a source to a destination according to addressing, topology, constraints, and routing policies. In Cloud Networking, the focus is on concept-level scope: the defining mechanism, properties, constraints, and application criteria; curricular context is recorded in Concept_Category and Typical_Modules.', 'SSD_COURSE_028_M5_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_028_M5_S4', 'load balancing', '4', 'load balancing: Distribution of computational, network, or service workload across available resources to improve utilization, throughput, latency, or availability. In Cloud Networking, the focus is on concept-level scope: the defining mechanism, properties, constraints, and application criteria; curricular context is recorded in Concept_Category and Typical_Modules.', 'SSD_COURSE_028_M5_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_028_M5_S5', 'service discovery', '5', 'service discovery: Mechanisms by which services find the network locations or endpoints of other services. In Cloud Networking, the focus is on the analysis, design, implementation, interpretation, or evaluation of service discovery within Cloud Computing and Virtualization, particularly where the Cloud Networking module establishes its technical context.', 'SSD_COURSE_028_M5_S5', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_028_M5_S6', 'network security', '6', 'network security: Controls that protect cloud network traffic, interfaces, segments, and services from unauthorised access or attack. In Cloud Networking, the focus is on the analysis, design, implementation, interpretation, or evaluation of network security within Cloud Computing and Virtualization, particularly where the Cloud Networking module establishes its technical context.', 'SSD_COURSE_028_M5_S6', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_028_M6_S1', 'infrastructure as code', '1', 'infrastructure as code: Defining infrastructure configuration in machine-readable files so it can be provisioned and changed consistently. In Cloud Orchestration and Automation, the focus is on the analysis, design, implementation, interpretation, or evaluation of infrastructure as code within Cloud Computing and Virtualization, particularly where the Cloud Orchestration and Automation module establishes its technical context.', 'SSD_COURSE_028_M6_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_028_M6_S2', 'configuration management', '2', 'configuration management: Controlling and maintaining system configuration states so that infrastructure remains consistent, reproducible, and auditable. In Cloud Orchestration and Automation, the focus is on the analysis, design, implementation, interpretation, or evaluation of configuration management within Cloud Computing and Virtualization, particularly where the Cloud Orchestration and Automation module establishes its technical context.', 'SSD_COURSE_028_M6_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_028_M6_S3', 'orchestration', '3', 'orchestration: Automated coordination of multiple resources, containers, services, or deployment steps. In Cloud Orchestration and Automation, the focus is on the analysis, design, implementation, interpretation, or evaluation of orchestration within Cloud Computing and Virtualization, particularly where the Cloud Orchestration and Automation module establishes its technical context.', 'SSD_COURSE_028_M6_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_028_M6_S4', 'service deployment', '4', 'service deployment refers to the process of releasing and configuring an application or service on cloud infrastructure. In Cloud Orchestration and Automation, the focus is on the analysis, design, implementation, interpretation, or evaluation of service deployment within Cloud Computing and Virtualization, particularly where the Cloud Orchestration and Automation module establishes its technical context.', 'SSD_COURSE_028_M6_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_028_M6_S5', 'autoscaling policies', '5', 'autoscaling policies: Rules that determine when and how cloud resources are added or removed in response to workload conditions. In Cloud Orchestration and Automation, the focus is on the analysis, design, implementation, interpretation, or evaluation of autoscaling policies within Cloud Computing and Virtualization, particularly where the Cloud Orchestration and Automation module establishes its technical context.', 'SSD_COURSE_028_M6_S5', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_028_M7_S1', 'identity and access management', '1', 'identity and access management: Controls for identifying users or services and granting them appropriate access to cloud resources. In Cloud Security and Reliability, the focus is on the analysis, design, implementation, interpretation, or evaluation of identity and access management within Cloud Computing and Virtualization, particularly where the Cloud Security and Reliability module establishes its technical context.', 'SSD_COURSE_028_M7_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_028_M7_S2', 'encryption', '2', 'encryption: Transforming data using cryptographic methods so it cannot be read without the required key. In Cloud Security and Reliability, the focus is on the analysis, design, implementation, interpretation, or evaluation of encryption within Cloud Computing and Virtualization, particularly where the Cloud Security and Reliability module establishes its technical context.', 'SSD_COURSE_028_M7_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_028_M7_S3', 'isolation', '3', 'isolation: Keeping workloads, tenants, or security domains separated to prevent unintended access or interference. In Cloud Security and Reliability, the focus is on the analysis, design, implementation, interpretation, or evaluation of isolation within Cloud Computing and Virtualization, particularly where the Cloud Security and Reliability module establishes its technical context.', 'SSD_COURSE_028_M7_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_028_M7_S4', 'resilience', '4', 'resilience refers to the ability of a cloud service to continue or recover operation after component or infrastructure failures. In Cloud Security and Reliability, the focus is on the analysis, design, implementation, interpretation, or evaluation of resilience within Cloud Computing and Virtualization, particularly where the Cloud Security and Reliability module establishes its technical context.', 'SSD_COURSE_028_M7_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_028_M7_S5', 'backup and disaster recovery', '5', 'backup and disaster recovery: Practices for preserving recoverable copies of data and restoring services after data loss, equipment failure, or a disruptive event. In Cloud Security and Reliability, the focus is on the analysis, design, implementation, interpretation, or evaluation of backup and disaster recovery within Cloud Computing and Virtualization, particularly where the Cloud Security and Reliability module establishes its technical context.', 'SSD_COURSE_028_M7_S5', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_029_M1_S1', 'site planning', '1', 'site planning: Selecting and arranging a data-centre site and its supporting infrastructure with regard to power, cooling, connectivity, risk, capacity, and expansion. In Data Center Architecture and Facilities, the focus is on the analysis, design, implementation, interpretation, or evaluation of site planning within Data Center Operations and Infrastructure, particularly where the Data Center Architecture and Facilities module establishes its technical context.', 'SSD_COURSE_029_M1_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_029_M1_S2', 'rack layout', '2', 'rack layout refers to the physical arrangement of servers, network equipment, power equipment, and cabling within data-center racks. In Data Center Architecture and Facilities, the focus is on the analysis, design, implementation, interpretation, or evaluation of rack layout within Data Center Operations and Infrastructure, particularly where the Data Center Architecture and Facilities module establishes its technical context.', 'SSD_COURSE_029_M1_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_029_M1_S3', 'power distribution', '3', 'power distribution: Arrangement and operation of electrical equipment and conductors used to distribute power from sources or upstream systems to loads at the required voltage and reliability level. In Data Center Architecture and Facilities, the focus is on concept-level scope: the defining mechanism, properties, constraints, and application criteria; curricular context is recorded in Concept_Category and Typical_Modules.', 'SSD_COURSE_029_M1_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_029_M1_S4', 'cooling architecture', '4', 'cooling architecture refers to the arrangement of cooling equipment, heat-transfer paths, airflow, and controls used to remove heat from data-centre spaces and IT equipment. In Data Center Architecture and Facilities, the focus is on the analysis, design, implementation, interpretation, or evaluation of cooling architecture within Data Center Operations and Infrastructure, particularly where the Data Center Architecture and Facilities module establishes its technical context.', 'SSD_COURSE_029_M1_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_029_M1_S5', 'physical security', '5', 'physical security: Measures that protect data-center facilities and equipment from unauthorised physical access, damage, or tampering. In Data Center Architecture and Facilities, the focus is on the analysis, design, implementation, interpretation, or evaluation of physical security within Data Center Operations and Infrastructure, particularly where the Data Center Architecture and Facilities module establishes its technical context.', 'SSD_COURSE_029_M1_S5', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_029_M2_S1', 'server architectures', '1', 'server architectures refers to the hardware and system architectures used to provide compute capacity, including processors, memory, storage interfaces, accelerators, and interconnects. In Compute Infrastructure, the focus is on the analysis, design, implementation, interpretation, or evaluation of server architectures within Data Center Operations and Infrastructure, particularly where the Compute Infrastructure module establishes its technical context.', 'SSD_COURSE_029_M2_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_029_M2_S2', 'processors', '2', 'processors: Central processing units that execute instructions and perform general-purpose computational work. In Compute Infrastructure, the focus is on the analysis, design, implementation, interpretation, or evaluation of processors within Data Center Operations and Infrastructure, particularly where the Compute Infrastructure module establishes its technical context.', 'SSD_COURSE_029_M2_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_029_M2_S3', 'memory', '3', 'memory: High-speed storage used by processors to hold active instructions and data during computation. In Compute Infrastructure, the focus is on the analysis, design, implementation, interpretation, or evaluation of memory within Data Center Operations and Infrastructure, particularly where the Compute Infrastructure module establishes its technical context.', 'SSD_COURSE_029_M2_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_029_M2_S4', 'storage controllers', '4', 'storage controllers: Hardware or software components that manage data transfers between compute systems and storage devices or arrays. In Compute Infrastructure, the focus is on the analysis, design, implementation, interpretation, or evaluation of storage controllers within Data Center Operations and Infrastructure, particularly where the Compute Infrastructure module establishes its technical context.', 'SSD_COURSE_029_M2_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_029_M2_S5', 'accelerators', '5', 'accelerators: Specialised processors, such as GPUs or AI accelerators, designed to speed particular computational workloads. In Compute Infrastructure, the focus is on the analysis, design, implementation, interpretation, or evaluation of accelerators within Data Center Operations and Infrastructure, particularly where the Compute Infrastructure module establishes its technical context.', 'SSD_COURSE_029_M2_S5', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_029_M2_S6', 'hardware lifecycle', '6', 'hardware lifecycle: Management of equipment from procurement and installation through operation, maintenance, upgrade, and retirement. In Compute Infrastructure, the focus is on the analysis, design, implementation, interpretation, or evaluation of hardware lifecycle within Data Center Operations and Infrastructure, particularly where the Compute Infrastructure module establishes its technical context.', 'SSD_COURSE_029_M2_S6', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_029_M3_S1', 'Redundant Array of Independent Disks (RAID)', '1', 'Redundant Array of Independent Disks (RAID) refers to a storage technique that combines multiple drives to provide defined levels of performance, redundancy, or fault tolerance. In Storage and Data Infrastructure, the focus is on the analysis, design, implementation, interpretation, or evaluation of RAID within Data Center Operations and Infrastructure, particularly where the Storage and Data Infrastructure module establishes its technical context.', 'SSD_COURSE_029_M3_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_029_M3_S2', 'Storage Area Network (SAN)', '2', 'Storage Area Network (SAN) refers to a dedicated storage network that provides block-level access to shared storage systems. In Storage and Data Infrastructure, the focus is on the analysis, design, implementation, interpretation, or evaluation of SAN within Data Center Operations and Infrastructure, particularly where the Storage and Data Infrastructure module establishes its technical context.', 'SSD_COURSE_029_M3_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_029_M3_S3', 'Network Attached Storage (NAS)', '3', 'Network Attached Storage (NAS) refers to a network-attached storage system that provides shared file-level access to data. In Storage and Data Infrastructure, the focus is on the analysis, design, implementation, interpretation, or evaluation of NAS within Data Center Operations and Infrastructure, particularly where the Storage and Data Infrastructure module establishes its technical context.', 'SSD_COURSE_029_M3_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_029_M3_S4', 'object storage', '4', 'object storage refers to a storage architecture in which data are managed as objects containing payload data, metadata, and a unique identifier within a logical namespace. In Storage and Data Infrastructure, the focus is on concept-level scope: the defining mechanism, properties, constraints, and application criteria; curricular context is recorded in Concept_Category and Typical_Modules.', 'SSD_COURSE_029_M3_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_029_M3_S5', 'backup', '5', 'backup refers to a separate copy of data maintained so it can be restored after deletion, corruption, or system failure. In Storage and Data Infrastructure, the focus is on the analysis, design, implementation, interpretation, or evaluation of backup within Data Center Operations and Infrastructure, particularly where the Storage and Data Infrastructure module establishes its technical context.', 'SSD_COURSE_029_M3_S5', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_029_M3_S6', 'data protection', '6', 'data protection: Measures that preserve the confidentiality, integrity, availability, and recoverability of data throughout its storage, processing, and transfer. In Storage and Data Infrastructure, the focus is on the analysis, design, implementation, interpretation, or evaluation of data protection within Data Center Operations and Infrastructure, particularly where the Storage and Data Infrastructure module establishes its technical context.', 'SSD_COURSE_029_M3_S6', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_029_M4_S1', 'topologies', '1', 'topologies: Physical or logical arrangements describing how data-center network devices and links are interconnected. In Data Center Networking, the focus is on the analysis, design, implementation, interpretation, or evaluation of topologies within Data Center Operations and Infrastructure, particularly where the Data Center Networking module establishes its technical context.', 'SSD_COURSE_029_M4_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_029_M4_S2', 'switching', '2', 'switching: Forwarding network frames between connected devices using switching decisions based on address information. In Data Center Networking, the focus is on the analysis, design, implementation, interpretation, or evaluation of switching within Data Center Operations and Infrastructure, particularly where the Data Center Networking module establishes its technical context.', 'SSD_COURSE_029_M4_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_029_M4_S3', 'routing', '3', 'routing: Selection of paths through a network from a source to a destination according to addressing, topology, constraints, and routing policies. In Data Center Networking, the focus is on concept-level scope: the defining mechanism, properties, constraints, and application criteria; curricular context is recorded in Concept_Category and Typical_Modules.', 'SSD_COURSE_029_M4_S3', 'Semantically_Audited', 'Active', '4.0') ON CONFLICT DO NOTHING;